/* Prose only, worked out first. The article's own words in their own order —
   anything an earlier run of this migration added is dropped and rebuilt, which
   is what makes a second run produce what the first one did.

   In its own table rather than a LATERAL, because `UPDATE ... FROM` cannot
   reach the row being updated from a lateral subquery. */
create temporary table kb_prose on commit drop as
select a.id,
       coalesce((select jsonb_agg(e order by n)
                   from jsonb_array_elements(a.body) with ordinality t(e, n)
                  where e ->> 'kind' = 'prose'), '[]'::jsonb) as blocks
  from public.kb_articles a
 where a.id in (select id from kb_media);

update public.kb_articles a set body =
  jsonb_build_array(p.blocks -> 0, m.img)
  || coalesce((select jsonb_agg(e) from jsonb_array_elements(p.blocks) with ordinality t(e, n)
                where n > 1), '[]'::jsonb)
  || case when m.vid is null then '[]'::jsonb else jsonb_build_array(m.vid) end
from kb_media m
join kb_prose p on p.id = m.id
where a.id = m.id and jsonb_array_length(p.blocks) > 0;

do $$
declare n integer; bad text;
begin
  select count(*) into n from public.kb_articles
   where view is not null and not (body::text like '%"image"%');
  if n > 0 then raise exception '% articles about a screen still have no picture of it.', n; end if;

  /* The photograph is gone, and nothing else points outside this marketplace. */
  select string_agg(a.id, ', ') into bad from public.kb_articles a,
    lateral jsonb_array_elements(a.body) e
   where e ->> 'kind' = 'image'
     and e ->> 'src' not like 'https://playukebhnkrdrcsorhj.supabase.co/storage/v1/object/public/kb-assets/%';
  if bad is not null then
    raise exception 'These articles still illustrate themselves with somebody else''s picture: %', bad;
  end if;

  /* Every picture describes itself. The reader most likely to need the
     description is the one who cannot see it. */
  select string_agg(a.id, ', ') into bad from public.kb_articles a,
    lateral jsonb_array_elements(a.body) e
   where e ->> 'kind' = 'image' and coalesce(trim(e ->> 'alt'), '') = '';
  if bad is not null then raise exception 'Images with no alt text: %', bad; end if;

  /* And every video is on a host this marketplace will frame — the same rule
     `kb_embeddable` holds a save to, checked over what is actually on file. */
  select string_agg(a.id, ', ') into bad from public.kb_articles a,
    lateral jsonb_array_elements(a.body) e
   where e ->> 'kind' = 'video' and not public.kb_embeddable(e ->> 'url');
  if bad is not null then raise exception 'Videos this marketplace will not frame: %', bad; end if;

  select count(distinct e ->> 'url') into n from public.kb_articles a,
    lateral jsonb_array_elements(a.body) e where e ->> 'kind' = 'video';
  if n < 4 then
    raise exception 'Only % video URL forms on file; the conversion branches are not all exercised.', n;
  end if;
end $$;
